"\"\"\"删除哨兵后强制重拉云端最新数据库\"\"\"\nimport os\n\n# 1. 加载 .env\nenv_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), '.env')\nif os.path.exists(env_path):\n    for line in open(env_path, encoding='utf-8').read().splitlines():\n        line = line.strip()\n        if line and not line.startswith('#') and '=' in line:\n            k, v = line.split('=', 1)\n            v = v.strip().strip('\\\'').strip('\\\"')\n            if k.strip() == 'HF_TOKEN':\n                os.environ['HF_TOKEN'] = v\n\n# 2. 删除哨兵\nimport v6_data_engine\nsentinel = v6_data_engine._DB_INIT_SENTINEL\nif sentinel.exists():\n    sentinel.unlink()\n    print(f'哨兵已删除: {sentinel}')\nelse:\n    print(f'哨兵不存在: {sentinel}')\n\n# 3. 强制拉取\nv6_data_engine.pull_database_from_hub()\nprint('PULL_DONE')\n\n# 4. 检查现状\nimport sqlite3\nfrom datetime import datetime, timezone, timedelta\nBJ = timezone(timedelta(hours=8))\nf = lambda ts: datetime.fromtimestamp(ts, BJ).strftime('%Y-%m-%d %H:%M:%S') if ts else None\nconn = sqlite3.connect(str(v6_data_engine._get_db_path()))\nconn.row_factory = sqlite3.Row\nrows = conn.execute(\n    \"SELECT rowid, signal_id, timestamp, direction, exit_reason, exit_timestamp, pnl_r \"\n    \"FROM trade_snapshots ORDER BY rowid\").fetchall()\nprint(f'\\n=== 总行数: {len(rows)} ===')\nfor r in rows:\n    print(f\"row{r['rowid']:2d} | open={f(r['timestamp'])} | dir={r['direction']:5s} | \"\n          f\"reason={str(r['exit_reason']):26s} | exit={f(r['exit_timestamp'])} | pnl={r['pnl_r']}\")\nconn.close()\n"